<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><title>Order {{ $order->public_reference }}</title><style>body{font:14px/1.6 Arial,sans-serif;max-width:850px;margin:40px auto;color:#193328}table{width:100%;border-collapse:collapse;margin:25px 0}th,td{border-bottom:1px solid #ddd;padding:12px;text-align:left}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print</button><h1>R&R Care BD</h1><h2>COD order / packing slip</h2><p>Reference: {{ $order->public_reference }}<br>Date: {{ $order->created_at->timezone('Asia/Dhaka')->format('d M Y H:i') }}<br>Status: {{ $order->status->value }}</p><p>{{ $order->name }}<br>{{ $order->phone }}<br>{{ $order->address }}<br>{{ $order->delivery_zone_name }}</p><table><thead><tr><th>Product / SKU</th><th>Qty</th><th>Unit</th><th>Total</th></tr></thead><tbody>@foreach($order->items as $item)<tr><td>{{ $item->product_name }}<br>{{ $item->sku_code }} / {{ $item->sku_label }}</td><td>{{ $item->quantity }}</td><td>{{ \App\Services\PricingService::money($item->unit_minor) }}</td><td>{{ \App\Services\PricingService::money($item->unit_minor*$item->quantity) }}</td></tr>@endforeach</tbody></table><p>Delivery: {{ \App\Services\PricingService::money($order->delivery_minor) }}</p><h2>Collect on delivery: {{ \App\Services\PricingService::money($order->total_minor) }}</h2><p>Customer note: {{ $order->note }}</p></body></html>
